update backlink_source b set screen_status = v.status, http_status = v.code, final_url = v.final_url, check_error = v.err, checked_at = now() from (values
(#{r.id}::bigint, #{r.status}::text, #{r.httpStatus}::int, #{r.finalUrl}::text, #{r.error}::text)
) as v(id, status, code, final_url, err) where b.id = v.id
